IV. Remediation Recommendations
4.1 Critical Fix (P0 — Immediate Action Recommended)
Option A: Remove the Transparent Proxy Endpoint (Recommended)
If the /api/proxy/transparent endpoint is not required for core functionality, remove the route and controller entirely:
// app/router.js — Remove or comment out this line
// app.post(`/proxy/transparent`, 'proxy.transparentProxy')

// app/controller/proxy.js — Remove the transparentProxy method
Option B: Implement URL Whitelist for imgCorsProxy
// app/controller/proxy.js
const ALLOWED_HOSTS = [
  'your-cdn.example.com',
  'img.example.com',
];

async imgCorsProxy () {
  const { ctx } = this;
  const url = ctx.query['url'];
  const responseType = ctx.query['responseType'];

  // 1. Parse URL
  let urlInfo;
  try {
    urlInfo = new URL(url);
  } catch (e) {
    ctx.body = 'invalid url';
    return;
  }

  // 2. Enforce Host Whitelist (before making requests)
  if (!ALLOWED_HOSTS.some(h => urlInfo.hostname === h || urlInfo.hostname.endsWith('.' + h))) {
    ctx.body = 'host not allowed';
    return;
  }

  // 3. Perform additional DNS/IP security checks
  // ...
}
